unsigned long last = 0;
unsigned long seconds = 0;
void setup() {
  Serial.begin(115200);
  Serial.println(F("Belajar Arduino dimulai"));
}
void loop() {
  unsigned long now = millis();
  if (now - last >= 1000UL) {
    last = now;
    seconds++;
    Serial.print(F("Detik: "));
    Serial.println(seconds);
  }
}

