WiFiServer server(80);
void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  digitalWrite(LED_BUILTIN, LOW);
  Serial.begin(115200);
  networkReady = connectNetwork();
  if (!networkReady) { Serial.println(F("Koneksi gagal. Periksa AT/Wi-Fi lalu reset.")); return; }
  server.begin();
  Serial.print(F("Buka http://")); Serial.println(WiFi.localIP());
}
void loop() {
  if (!networkReady) return;
  WiFiClient client = server.accept();
  if (!client) return;
  char request[96] = {0};
  byte used = 0;
  unsigned long start = millis();
  bool firstLine = true, blank = true, complete = false;
  unsigned int received = 0;
  while (client.connected() && millis() - start < 8000UL && received < 2048) {
    if (!client.available()) continue;
    char c = client.read(); received++;
    if (firstLine && c != '\r' && c != '\n' && used < sizeof(request) - 1) request[used++] = c;
    if (c == '\n') {
      if (blank) { complete = true; break; }
      blank = true; firstLine = false;
    } else if (c != '\r') blank = false;
  }
  if (complete) {
    if (strcmp(request, "POST /on HTTP/1.1") == 0) digitalWrite(LED_BUILTIN, HIGH);
    if (strcmp(request, "POST /off HTTP/1.1") == 0) digitalWrite(LED_BUILTIN, LOW);
    client.println(F("HTTP/1.1 200 OK"));
    client.println(F("Content-Type: text/html; charset=utf-8"));
    client.println(F("Cache-Control: no-store"));
    client.println(F("Connection: close")); client.println();
    client.println(F("<!doctype html><html lang='id'><meta name='viewport' content='width=device-width'><title>LED UNO</title><h1>LED latihan</h1>"));
    client.print(F("<p>Status: "));
    client.print(digitalRead(LED_BUILTIN) ? F("ON") : F("OFF"));
    client.println(F("</p><form method='post' action='/on'><button>ON</button></form><form method='post' action='/off'><button>OFF</button></form></html>"));
  }
  client.stop();
}

