IPAddress receiver(192, 168, 1, 10); // ganti IP komputer lab
unsigned long lastSend = 0;
void setup() {
  Serial.begin(115200);
  networkReady = connectNetwork();
  Serial.println(networkReady ? F("Wi-Fi siap") : F("Koneksi gagal; periksa lalu reset"));
}
void loop() {
  if (!networkReady || millis() - lastSend < 10000UL) return;
  lastSend = millis();
  float celsius = analogRead(A0) * (5.0 / 1024.0) * 100.0;
  char number[16];
  dtostrf(celsius, 0, 1, number);
  char payload[80];
  snprintf(payload, sizeof(payload), "{\"deviceId\":\"uno-01\",\"temperatureC\":%s}", number);
  WiFiClient client;
  if (!client.connect(receiver, 8080)) { Serial.println(F("Server tidak terhubung")); return; }
  client.println(F("POST /telemetry HTTP/1.1"));
  client.print(F("Host: ")); client.print(receiver); client.println(F(":8080"));
  client.println(F("Content-Type: application/json"));
  client.print(F("Content-Length: ")); client.println(strlen(payload));
  client.println(F("Connection: close")); client.println();
  client.print(payload);
  unsigned long start = millis();
  while (client.connected() && millis() - start < 3000UL) {
    while (client.available()) Serial.write(client.read());
  }
  client.stop();
}
